# Mocked Environment for Travel Planning
from typing import List, Dict

# Mocked Data
flights = [
    {"flight_id": 101, "destination": "Paris", "date": "2023-10-15", "price": 300},
    {"flight_id": 102, "destination": "Paris", "date": "2023-10-15", "price": 280},
    {"flight_id": 103, "destination": "Paris", "date": "2023-10-16", "price": 250}
]

hotels = [
    {"hotel_id": 201, "name": "River View", "destination": "Paris", "price_per_night": 140, "latitude": 48.8588, "longitude": 2.2945},
    {"hotel_id": 202, "name": "Downtown Inn", "destination": "Paris", "price_per_night": 160, "latitude": 48.8566, "longitude": 2.3522},
    {"hotel_id": 203, "name": "Eiffel Stay", "destination": "Paris", "price_per_night": 130, "latitude": 48.8579, "longitude": 2.2965}
]

landmarks = [
    {"name": "Eiffel Tower", "latitude": 48.8584, "longitude": 2.2945}
]

# Mocked Functions
def get_available_flights(destination: str, date: str) -> List[Dict]:
    """Return flights matching destination and date."""
    return [f for f in flights if f["destination"] == destination and f["date"] == date]

def get_hotels_in_budget(destination: str, max_price_per_night: float) -> List[Dict]:
    """Return hotels under max price per night."""
    return [h for h in hotels if h["destination"] == destination and h["price_per_night"] <= max_price_per_night]

def calculate_distance_from_landmark(hotel_id: int, landmark_name: str) -> float:
    """Calculate Euclidean distance between hotel and landmark (simplified)."""
    hotel = next(h for h in hotels if h["hotel_id"] == hotel_id)
    landmark = next(l for l in landmarks if l["name"] == landmark_name)
    lat_diff = abs(hotel["latitude"] - landmark["latitude"])
    lon_diff = abs(hotel["longitude"] - landmark["longitude"])
    return round((lat_diff + lon_diff) * 111, 2)  # Approx km conversion

def get_cheapest_flight(flights: List[Dict]) -> Dict:
    """Return flight with lowest price."""
    return min(flights, key=lambda x: x["price"])

def calculate_total_cost(flight_price: float, hotel_price_per_night: float, nights: int) -> float:
    """Calculate total trip cost."""
    return flight_price + hotel_price_per_night * nights

