books = [
    {"title": "The Great Gatsby", "author": "F. Scott Fitzgerald", "isbn": "9780743273565", "copies_available": 3, "holds": []},
    {"title": "1984", "author": "George Orwell", "isbn": "9780451524935", "copies_available": 0, "holds": []},
    {"title": "Brave New World", "author": "Aldous Huxley", "isbn": "9780060850524", "copies_available": 0, "holds": []},
]

def search_books(search_term: str) -> list[dict]:
    results = []
    for book in books:
        if search_term.lower() in book["title"].lower() or search_term.lower() in book["author"].lower():
            results.append(book)
    return results

def check_availability(isbn: str) -> int:
    for book in books:
        if book["isbn"] == isbn:
            return book["copies_available"]
    return 0

def place_hold(isbn: str, user_id: str) -> str:
    for book in books:
        if book["isbn"] == isbn:
            book["holds"].append(user_id)
            return "Hold placed successfully. Expires on 2023-10-10."
    return "ISBN not found."

def calculate_late_fee(days_late: int) -> float:
    return 2.0 * days_late

