    {"course_id": 102, "name": "Statistics", "prerequisites": []},
    {"course_id": 103, "name": "Advanced Machine Learning", "prerequisites": [101, 102]}
]

enrollments = [
    {"student_id": 1, "course_id": 101},
    {"student_id": 1, "course_id": 102},
