    {"student_id": 1, "course_id": 102, "score": 90.0},
    {"student_id": 2, "course_id": 101, "score": 78.5}
]

def get_student_id(student_name: str) -> int | None:
    for student in students:
        if student["name"] == student_name:
            return student["student_id"]
    return None

def get_enrolled_courses(student_id: int) -> list[int]:
    return [e["course_id"] for e in enrollments if e["student_id"] == student_id]

def get_course_prerequisites(course_id: int) -> list[int]:
    for course in courses:
        if course["course_id"] == course_id:
            return course["prerequisites"]
    return []

def get_course_id_by_name(course_name: str) -> int | None:
    for course in courses:
        if course["name"] == course_name:
            return course["course_id"]
    return None

def get_grade(student_id: int, course_id: int) -> float | None:
    for grade in grades:
        if grade["student_id"] == student_id and grade["course_id"] == course_id:
            return grade["score"]
    return None

