]

customers = [
    {"id": 1, "name": "Alice", "reservations": [101]},
    {"id": 2, "name": "Bob", "reservations": []}
]

def get_available_rooms(room_type: str) -> list[int]:
    return [room["number"] for room in rooms if room["type"] == room_type and room["available"]]

def book_room(room_number: int, customer_id: int) -> bool:
    for room in rooms:
        if room["number"] == room_number and room["available"]:
            for customer in customers:
                if customer["id"] == customer_id:
                    room["available"] = False
                    customer["reservations"].append(room_number)
                    return True
    return False

def get_room_price(room_number: int) -> float:
    for room in rooms:
        if room["number"] == room_number:
            return room["price"]
    return 0.0

def get_customer_reservations(customer_id: int) -> list[int]:
    for customer in customers:
        if customer["id"] == customer_id:
            return customer["reservations"].copy()
    return []

