# Mocked library environment with book management functions
from datetime import datetime
from typing import Dict, List, Union

# Mocked data
books = [
    {"id": 1, "title": "1984", "author": "George Orwell", "available": False},
    {"id": 2, "title": "The Great Gatsby", "author": "F. Scott Fitzgerald", "available": False},
    {"id": 3, "title": "Dune", "author": "Frank Herbert", "available": True}
]

users = [
    {"id": 123, "name": "Alice", "borrowed": [1, 2], "reservations": []},
    {"id": 456, "name": "Bob", "borrowed": [], "reservations": [3]}
]

due_dates = {
    1: datetime(2023, 10, 25),
    2: datetime(2023, 10, 30)
}

reservations = [
    {"book_id": 1, "user_id": 456, "status": "active"}
]

def get_borrowed_books(user_id: int) -> List[int]:
    """Return list of book IDs borrowed by user"""
    return next((u["borrowed"] for u in users if u["id"] == user_id), [])

def check_reservation(book_id: int) -> bool:
    """Check if book has active reservations"""
    return any(r["status"] == "active" for r in reservations if r["book_id"] == book_id)

def check_due_date(book_id: int, user_id: int) -> Union[datetime, None]:
    """Get due date for a borrowed book"""
    if book_id in get_borrowed_books(user_id):
        return due_dates.get(book_id)
    return None

def renew_loan(book_id: int, user_id: int) -> bool:
    """Attempt to renew book loan if eligible"""
    if book_id in get_borrowed_books(user_id) and not check_reservation(book_id):
        due_dates[book_id] = due_dates[book_id].replace(day=due_dates[book_id].day+7)
        return True
    return False

