    "P002": {"stock": 0, "price": 200.0, "weight": 5.0},
}

users = {
    "U001": {"purchase_history": ["P001", "P003"], "location": "US"},
    "U002": {"purchase_history": [], "location": "EU"},
}

discount_rules = {
    "US": {"min_purchases": 2, "discount_rate": 0.1},
    "EU": {"min_purchases": 1, "discount_rate": 0.15},
}

def get_product_stock(product_id: str) -> int:
    return products.get(product_id, {}).get("stock", 0)

def get_product_price(product_id: str) -> float:
    return products.get(product_id, {}).get("price", 0.0)

def check_user_location(user_id: str) -> str:
    return users.get(user_id, {}).get("location")

def get_user_purchase_count(user_id: str) -> int:
    return len(users.get(user_id, {}).get("purchase_history", []))

def calculate_shipping_cost(product_id: str, location: str, quantity: int) -> float:
    product = products.get(product_id)
    if not product:
        return 0.0
    weight = product["weight"] * quantity
    if location == "US":
        return weight * 5.0
    elif location == "EU":
        return weight * 7.0
    else:
        return 0.0

def calculate_discount(user_id: str, subtotal: float) -> float:
    location = check_user_location(user_id)
    if not location:
        return 0.0
    purchase_count = get_user_purchase_count(user_id)
    rule = discount_rules.get(location, {})
    if purchase_count >= rule.get("min_purchases", 0):
        return subtotal * rule.get("discount_rate", 0.0)
    return 0.0

