members = [
    {"member_id": "123", "name": "John Doe", "active": False, "reserved_books": []},
    {"member_id": "456", "name": "Jane Smith", "active": True, "reserved_books": []}
]

def get_book_availability(isbn: str) -> dict:
    """Returns the available copies of a book by ISBN."""
    for book in books:
        if book["isbn"] == isbn:
            return {"isbn": isbn, "available_copies": book["available_copies"]}
    return {"isbn": isbn, "available_copies": 0}

def get_member_status(member_id: str) -> dict:
    """Returns a member's active status and reserved books by member ID."""
    for member in members:
        if member["member_id"] == member_id:
            return {
                "member_id": member_id,
                "active": member["active"],
                "reserved_books": member["reserved_books"]
            }
    return {"member_id": member_id, "active": False, "reserved_books": []}

def reserve_book(member_id: str, isbn: str) -> str:
    """Reserves a book for a member if available and member is active."""
    member = next((m for m in members if m["member_id"] == member_id), None)
    if not member:
        return "Member not found."
    if not member["active"]:
        return f"Member {member_id} is not active."
    book = next((b for b in books if b["isbn"] == isbn), None)
    if not book:
        return "Book not found."
    if book["available_copies"] <= 0:
        return f"No available copies for book {isbn}."
    member["reserved_books"].append(isbn)
    book["available_copies"] -= 1
    return f"Book {isbn} reserved successfully by member {member_id}."

def renew_loan(member_id: str, isbn: str) -> str:
    """Renews a loan for a member if active and book is reserved."""
    member = next((m for m in members if m["member_id"] == member_id), None)
    if not member:
        return "Member not found."
    if not member["active"]:
        return f"Member {member_id} is not active."
    if isbn not in member["reserved_books"]:
        return f"Member {member_id} has not reserved book {isbn}."
    return f"Loan renewed successfully for member {member_id} and book {isbn}."

