]

# Mocked functions
def get_book_details(book_id: int) -> dict:
    """Return book details by ID or empty dict if not found"""
    return next((b for b in books if b["id"] == book_id), {})

def check_availability(book_id: int) -> bool:
    """Check if a book has available copies"""
    book = get_book_details(book_id)
    return book.get("available_copies", 0) > 0 if book else False

def reserve_book(user_id: int, book_id: int) -> bool:
    """Reserve a book if available and update reservations"""
    user = next((u for u in users if u["id"] == user_id), None)
    book = get_book_details(book_id)

    if user and book and book["available_copies"] > 0:
        book["reserved"] += 1
        user["reservations"].append(book_id)
        return True
    return False

def renew_loan(user_id: int, book_id: int) -> bool:
    """Renew a book loan if user has no fines and possesses the book"""
    user = next((u for u in users if u["id"] == user_id), None)
    book = get_book_details(book_id)

    if user and book and book_id in user["borrowed"] and user["fines"] <= 0:
        return True
    return False

def calculate_fine(user_id: int) -> float:
    """Return current fines for a user"""
    user = next((u for u in users if u["id"] == user_id), None)
    return user.get("fines", 0.0) if user else 0.0

def pay_fine(user_id: int, amount: float) -> bool:
    """Pay fines for a user"""
    user = next((u for u in users if u["id"] == user_id), None)
    if user and amount >= user["fines"]:
        user["fines"] = 0.0
        return True
    elif user and amount < user["fines"]:
        user["fines"] -= amount
        return True
    return False

